	ranked, err := ScanRealityTargets(ctx, exec, "")

if err != nil {
	return RealityScanResult{}, "", err
}
best, _, err := BestRealityTarget(ranked)
if err != nil {
	return RealityScanResult{}, "", err
}
full, err := ScanRealityTargets(ctx, exec, best.Target)

if err != nil {
	return RealityScanResult{}, "", err
